components.customDefaultValue:
let loondienstAfgelopen3maanden = false;
let uitkeringAfgelopen3Maanden = false;
let pensioenAfgelopen3Maanden = false;
let svbAfgelopen3Maanden  = false;

if (data.pv?.inkomstenVanuitBronnen?.loondienst?.length > 0) {
    loondienstAfgelopen3maanden = (data.pv?.inkomstenVanuitBronnen?.loondienst ?? [])?.some(item =>
        item.opgaven.some(opgave => {
            const threeMonthsAgo = moment(data.gegevensVanuitAanvraag?.startDatum).subtract(3, 'months');
            if (!opgave.datumEindOpgave && opgave.datumEindOpgave !== '') return false;
            const datumEind = moment(opgave.datumEindOpgave);
            return threeMonthsAgo.isSameOrBefore(datumEind);
        })
    );
}

if (data.pv?.inkomstenVanuitBronnen?.uitkering?.length > 0) {
    uitkeringAfgelopen3Maanden = (data.pv?.inkomstenVanuitBronnen?.uitkering ?? [])?.some(item =>
        item.opgaven.some(opgave => {
            const threeMonthsAgo = moment(data.gegevensVanuitAanvraag?.startDatum).subtract(3, 'months');
            if (!opgave.datumEindOpgave && opgave.datumEindOpgave !== '') return false;
            const datumEind = moment(opgave.datumEindOpgave);
            return threeMonthsAgo.isSameOrBefore(datumEind);
        })
    );
}



if (data.pv?.inkomstenVanuitBronnen?.pensioen?.length > 0) {
    pensioenAfgelopen3Maanden = (data.pv?.inkomstenVanuitBronnen?.pensioen ?? [])?.some(item =>
        item.opgaven.some(opgave => {
            const threeMonthsAgo = moment(data.gegevensVanuitAanvraag?.startDatum).subtract(3, 'months');
            if (!opgave.datumEindOpgave && opgave.datumEindOpgave !== '') return false;
            const datumEind = moment(opgave.datumEindOpgave);
            return threeMonthsAgo.isSameOrBefore(datumEind);
        })
    );
}


if (data.pv?.svbUitkeringenVanuitBronnen?.length > 0) {
    svbAfgelopen3Maanden = (data.pv?.svbUitkeringenVanuitBronnen ?? [])?.some(item =>
        item.periodes.some(opgave => {
            const threeMonthsAgo = moment(data.gegevensVanuitAanvraag?.startDatum).subtract(3, 'months');
            if (!opgave.datumEindUitkeringsperiode && opgave.datumEindOpgave !== '') return false;
            const datumEind = moment(opgave.datumEindUitkeringsperiode);
            return threeMonthsAgo.isSameOrBefore(datumEind);
        })
    );
}


let isLoondienst = (data.pv?.inkomstenVanuitAanvraag?.loondienst?.length > 0 || loondienstAfgelopen3maanden);
let isUitkering = (data.pv.inkomstenVanuitAanvraag?.pensioenen?.length > 0 || data.pv.inkomstenVanuitAanvraag?.uitkeringTypes?.length > 0 || data.pv.inkomstenVanuitBronnen?.pensioen?.length > 0 || pensioenAfgelopen3Maanden || uitkeringAfgelopen3Maanden || svbAfgelopen3Maanden);
let isOnderneming = _.isNumber(data.pv?.inkomstenVanuitAanvraag?.onderneming?.totaalBedrag);
let isOverigInkomsten = (data.pv.kinderAlimentatieVanuitAanvraag?.ontvangtAlimentatie === 'JA' || data.pv.partnerAlimentatieVanuitAanvraag?.ontvangtAlimentatie === 'JA' || data.pv?.inkomstenVanuitAanvraag?.overig?.totaalBedrag > 0 || data.pv?.inkomstenVanuitAanvraag?.onderhuur?.totaalBedrag > 0 || data.pv?.inkomstenVanuitAanvraag?.inkomstenBuitenland?.nettoInkomstenBuitenland > 0 || data.pv?.inkomstenVanuitAanvraag?.heffingskorting?.totaalBedrag > 0)

const allFalse = Object.values(instance.component.defaultValue).every(v => v === false);
if (allFalse) {
    value = {
        "loondienst": isLoondienst,
        "uitkeringenPensioenenEnStudiefinanciering": isUitkering,
        "onderneming": isOnderneming,
        "overigeInkomsten": isOverigInkomsten,
        "geenInkomstenVaststellen": false
    };
} else {
    value = instance.component.defaultValue;
}

